class Solution {
public:
    int climbStairs(int n) {
        long long res[2][2] = {{1, 0}, {0, 1}};
        long long base[2][2] = {{1, 1}, {1, 0}};

        while (n > 0) {
            if (n & 1) {
                long long a = res[0][0] * base[0][0] + res[0][1] * base[1][0];
                long long b = res[0][0] * base[0][1] + res[0][1] * base[1][1];
                long long c = res[1][0] * base[0][0] + res[1][1] * base[1][0];
                long long d = res[1][0] * base[0][1] + res[1][1] * base[1][1];
                res[0][0] = a; res[0][1] = b; res[1][0] = c; res[1][1] = d;
            }
            long long a = base[0][0] * base[0][0] + base[0][1] * base[1][0];
            long long b = base[0][0] * base[0][1] + base[0][1] * base[1][1];
            long long c = base[1][0] * base[0][0] + base[1][1] * base[1][0];
            long long d = base[1][0] * base[0][1] + base[1][1] * base[1][1];
            base[0][0] = a; base[0][1] = b; base[1][0] = c; base[1][1] = d;

            n >>= 1;
        }

        return res[0][0];
    }
};
